    CreateWindowExA
    DestroyWindow
    GetCursorPos
    SetCursorPos
    SetCursor
    DialogBoxParamA
    EndDialog
    SetWindowLongA
    GetWindowLongA
    DrawTextA
}

binkw32 {
    _BinkOpen@8
    _BinkClose@4
    _BinkCopyToBuffer@28
    _BinkWait@4
}
